use super::{Generation2dSnapshot,Generation2dSnapshotRead};
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::*};
#[path="../../../../../../../../../../🫀️core/🧬️generation/🪶️sqlite/🧫️fixtures/🦀️.rs"]mod neutral;
fn fixture()->Generation2dSnapshotRead{let(host_snapshot,generation)=neutral::fixture(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json"));Generation2dSnapshotRead::new(Generation2dSnapshot{host_snapshot,generation})}
fn project(s:&Generation2dSnapshot)->SqliteDatabase{s.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn restore(d:&SqliteDatabase)->Result<Generation2dSnapshotRead,String>{Generation2dSnapshot::from_sqlite_database(d,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).map(Generation2dSnapshotRead::new)}
#[test]fn sqlite_snapshot_procedural_generation2d_full_owned_state(){let s=fixture();let d=project(&s);assert_eq!(d.tables.len(),36);let bytes=export_sqlite_database(&d,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let restored=restore(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(project(&restored),d);assert_eq!(restored.host_snapshot.camera.x.to_bits(),0x8000000000000000);assert_eq!(restored.host_snapshot.camera.y.to_bits(),0x7ff0000000000000);assert_eq!(restored.generation.selected_generation_id.as_deref(),Some(""));let default=Generation2dSnapshotRead::new(Generation2dSnapshot::default());assert_eq!(project(&restore(&project(&default)).unwrap()),project(&default));}
#[test]fn sqlite_snapshot_procedural_generation2d_independent_sqlite_edit(){use std::io::Write;use std::process::{Command,Stdio};let bytes=export_sqlite_database(&project(&fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');if(d.query('SELECT count(*) AS n FROM generation_widget').get().n!==9)throw Error('widget variants');if(d.query(\"SELECT unsigned_value FROM generation_value WHERE kind='unsigned' AND unsigned_value='18446744073709551615'\").all().length!==1)throw Error('full unsigned');if(d.query(\"SELECT count(*) AS n FROM generation_value WHERE kind='bytes'\").get().n!==2)throw Error('typed bytes');d.query(\"UPDATE generation_note_widget SET text='independent SQLite 日本'\").run();await Bun.write(Bun.stdout,d.serialize());";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));let s=restore(&import_sqlite_database(&output.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();if let semio_framework_artifact_flow_flow::Widget::InputNote{text,..}=&s.host_snapshot.widgets[2]{assert_eq!(text,"independent SQLite 日本")}else{panic!("note kind")}}
#[test]fn sqlite_snapshot_procedural_generation2d_bad_structure_and_admission(){let d=project(&fixture());for case in 0..5{let mut bad=d.clone();match case{0=>bad.table_mut("generation_widget").unwrap().rows[0].values[2]=SqliteValue::Integer(99),1=>bad.table_mut("generation_neural_entry").unwrap().rows[0].values[4]=SqliteValue::Integer(999999),2=>bad.table_mut("generation_note_widget").unwrap().rows.clear(),3=>bad.table_mut("generation_document").unwrap().rows[0].values[1]=SqliteValue::Integer(999),_=>bad.table_mut("generation_host").unwrap().rows[0].values[5]=SqliteValue::Integer(1)}assert!(restore(&bad).is_err(),"case {case}");}assert!(Generation2dSnapshot::from_sqlite_database(&d,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:16,..SqliteDatabaseLimits::default()})).is_err());assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());}

#[test]
fn sqlite_snapshot_procedural_generation2d_erased_native_encodings_and_retained_refusals(){
 let mut source=Generation2dSnapshotRead::new(Generation2dSnapshot::default());source.host_snapshot.schema="retained owned 日本".into();source.host_snapshot.widgets.push(semio_framework_artifact_flow_flow::Widget::InputNote{id:"owned note".into(),text:"persisted exact 日本".into()});
 let codec=store::ArtifactCodec::bare::<Generation2dSnapshot,crate::Generation2dMutation>(crate::GENERATION_2D_SCHEMA);let provider=codec.snapshot_sqlite.unwrap();assert_eq!(provider.snapshot_type,Some(std::any::TypeId::of::<Generation2dSnapshot>()));let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.procedural.generation2d".into(),standard:"1".into(),subset:"*".into()};
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(<Generation2dSnapshot as store::ArtifactPack>::encode_pack(&source)),SnapshotEncoding::Text=>store::os_io::IoPayload::Text(<Generation2dSnapshot as store::ArtifactDsl>::print_dsl(&source))};let database=(provider.export)(crate::GENERATION_2D_SCHEMA,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;let body=database.table("generation_note_widget").unwrap().rows.iter().find(|row|row.text(1).unwrap()=="persisted exact 日本");assert!(body.is_some());let bytes=export_sqlite_database(&database,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let imported=import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();assert_eq!((provider.import)(crate::GENERATION_2D_SCHEMA,&dialect,imported,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value,payload);let wrong=store::os_io::ArtifactDialect{subset:"unexpected".into(),..dialect.clone()};assert!((provider.export)(crate::GENERATION_2D_SCHEMA,&wrong,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err());assert!((provider.import)(crate::GENERATION_2D_SCHEMA,&dialect,database,encoding,&mut SqliteSnapshotControl::new(&mut |p|p.phase!=SqliteSnapshotPhase::EncodeNative,SqliteDatabaseLimits::default())).is_err());}
}
