#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_procedural_generation2d_actual_declaration_owned_io(){
 use semio_framework_os_kernel::io::io_mechanism::{io_export_sqlite_snapshot,io_import_sqlite_snapshot};
 semio_framework_plugin::Plugin::<semio_framework_plugin::app::NoPluginApp>::builder("procedural").label("Generation2d SQLite declaration").version("0.0.1").package_id("semio:procedural").artifact(crate::declaration().unwrap()).try_build().unwrap();
 let source=fixture();let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.procedural.generation2d".into(),standard:"1".into(),subset:"*".into()};for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let bytes=io_export_sqlite_snapshot(&dialect,&*source,encoding,SqliteDatabaseLimits::default(),&mut |_|true).await.unwrap().value;let restored=Generation2dSnapshotRead::new(io_import_sqlite_snapshot::<Generation2dSnapshot>(&dialect,&bytes,SqliteDatabaseLimits::default(),&mut |_|true).await.unwrap().value);assert_eq!(project(&restored),project(&source));}
}

#[test]fn sqlite_snapshot_procedural_generation2d_deep_owned_answers_and_partial_cancellation(){use semio_framework_os_kernel::DslValue;use semio_framework_artifact_playbook_playbook::{GenerationPlayState,FormGeneration};let mut value=DslValue::Bytes(vec![0,255]);for _ in 0..1024{value=DslValue::Array(vec![value]);}let mut s=Generation2dSnapshotRead::new(Generation2dSnapshot::default());let generation=GenerationPlayState{generations:vec![FormGeneration{id:"deep".into(),name:"".into(),values:std::collections::HashMap::from([("deep".into(),value)])}],selected_generation_id:None,preview_text:None}.into();std::mem::replace(&mut s.generation,generation).retire_cold();let d=project(&s);let back=restore(&d).unwrap();let mut v=back.generation.generations[0].values.get("deep").unwrap();for _ in 0..1024{if let DslValue::Array(values)=v{assert_eq!(values.len(),1);v=&values[0];}else{panic!("deep intrinsic array differs")}}assert!(matches!(v,DslValue::Bytes(bytes)if bytes==&[0,255]));let mut stopped=false;let mut callback=|p:SqliteSnapshotProgress|{if p.phase==SqliteSnapshotPhase::ReconstructSnapshot&&p.total==0&&p.completed>0{stopped=true;false}else{true}};assert!(Generation2dSnapshot::from_sqlite_database(&d,&mut SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default())).is_err());assert!(stopped);}
